# Andrew 单调链
pts.sort() by (x, y)
lower = []
for p in pts:
    while len(lower)>=2 and cross(lower[-2], lower[-1], p) <= 0: lower.pop()
    lower.append(p)
upper = []
for p in reversed(pts):
    while len(upper)>=2 and cross(upper[-2], upper[-1], p) <= 0: upper.pop()
    upper.append(p)
hull = lower[:-1] + upper[:-1]   # 逆时针，含所有凸包顶点

# cross(o,a,b) = (a-o)×(b-o)
# 用 <= 0 弹栈 → 不保留共线边界点；用 < 0 → 保留
